#!/usr/bin/env python3
"""Gate 3: unmodified JSON-RPC relayer client through BoundaryGuard proxy.

An unmodified Hyperlane relayer speaks ordinary JSON-RPC. This harness runs the
same query interface against four configurations and records source-event,
proxy-release, relay-submit, and destination-delivery timestamps for historical
delivered messages. Destination delivery times come from the frozen Hyperlane
trace when available; the client itself never uses proprietary APIs.
"""

from __future__ import annotations

